    /// 🤝️ The pair kerning between this scalar and the next scalar of its run at the worker's size — nothing for a run's last.
    pub kerning: f32,
    pub height: f32,
    pub generation: u64,
    pub revision: u64,
    pub atlas_page: u8,
    pub atlas_offset: u16,
    pub atlas_length: u8,
