#[derive(Clone, Copy)]
pub(crate) struct MountedLayoutIdentity {
    pub surface: UiSurfaceToken,
    pub generation: u64,
    pub revision: u64,
    pub theme_revision: u64,
    pub viewport_revision: u64,
}

impl MountedLayoutJob {
    pub(crate) fn try_new(tree: &UiTree, root: NodeId, identity: MountedLayoutIdentity, theme: Theme, width: f32, height: f32, block_reversed: bool, inline: ui_contract::FlowInline) -> Result<Self, MountedLayoutFault> {
        let MountedLayoutIdentity { surface, generation, revision, theme_revision, viewport_revision } = identity;
        let root_node = tree.node(root).ok_or(MountedLayoutFault::Stale)?;
        if !root_node.flags.contains(NodeFlags::DIRTY_LAYOUT) && !root_node.flags.contains(NodeFlags::SUBTREE_DIRTY) {
            return Err(MountedLayoutFault::Stale);
        }
        Ok(Self {
            stage: LayoutJobStage::CollectNodes,
            root,
            surface,
            generation,
            revision,
            theme_revision,
            viewport_revision,
            row_metrics: TreeRowMetrics::from_theme(&theme).with_inline(inline),
            theme,
            width,
            height,
            block_reversed,
            admission: if block_reversed { AdmissionPhase::VisitReversed } else { AdmissionPhase::Visit },
            pending_node: Some((root, None)),
            walk: Some(Box::new(ui_contract::UiFixedList::default())),
            nodes: Some(Box::new(ui_contract::UiFixedList::default())),
            glyphs: Some(Box::new(ui_contract::UiFixedList::default())),
            runs: Some(Box::new(ui_contract::UiFixedList::default())),
            lines: Some(Box::new(ui_contract::UiFixedList::default())),
            glyph_previews: Some(Box::new(ui_contract::UiFixedList::default())),
            atlas_candidate: RetainedAtlasCandidate::new(),
            results: Some(Box::new(ui_contract::UiFixedList::default())),
            rejected_node: None,
            rejected_walk: None,
            rejected_glyph: None,
            rejected_preview: None,
            rejected_run: None,
            rejected_line: None,
            rejected_result: None,
            text_node: None,
            text_byte: 0,
            text_part: 0,
            text_glyph_start: 0,
            run_cursor: 0,
            glyph_cursor: 0,
            line_cursor: 0,
            measure_cursor: 0,
            arrange_cursor: 0,
            collect_cursor: 0,
            child_scratch: Vec::new(),
            flex: FlexTree::new(),
            preview_cursor: 0,
            publish_cursor: 0,
            publication_committed: false,
            close_requested: false,
            #[cfg(test)]
            worker_thread_observed: false,
            fault: None,
            text_worker: DeterministicTextWorker::default(),
        })
    }

    pub(crate) fn identity(&self) -> (UiSurfaceToken, u64, u64, u64, u64, f32, f32) {
        (self.surface, self.generation, self.revision, self.theme_revision, self.viewport_revision, self.width, self.height)
    }

    pub(crate) fn stage(&self) -> LayoutJobStage {
        self.stage
    }

    pub(crate) fn is_admitted(&self) -> bool {
        self.stage != LayoutJobStage::CollectNodes
    }

    pub(crate) fn admit_one(&mut self, tree: &UiTree, cx: &mut semio_framework_job::StepContext<'_>) -> LayoutJobStep {
        if cx.is_cancelled() {
            return LayoutJobStep::Cancelled;
        }
        if cx.should_yield() {
            return LayoutJobStep::Yield { stage: self.stage, nodes: 0, glyphs: 0 };
        }
        cx.set_stage("Layout.AdmitOne");
        let progress = match self.admission {
            AdmissionPhase::Visit => self.admit_node_one(tree, false),
            AdmissionPhase::VisitReversed => self.admit_node_one(tree, true),
            AdmissionPhase::Text => self.admit_text_one(tree),
            AdmissionPhase::Unwind => self.unwind_one(tree),
            AdmissionPhase::Ready => {
                self.stage = LayoutJobStage::ShapeText;
                (0, 0)
            }
        };
        cx.consume_fuel(1);
        if let Some(fault) = self.fault {
            return LayoutJobStep::Fault(fault.label());
        }
        LayoutJobStep::Yield { stage: self.stage, nodes: progress.0, glyphs: progress.1 }
    }

    /// 🧩️ The panel content-projection ESCAPE HATCH. An `ExternalSlot` is the one node whose
    /// pixels this engine does not author: its host paints inside the solved rect. It used to
    /// fall into `Leaf`, which measures from arena children — a slot has none, so the band
    /// collapsed to nothing and any host-provided content (React hosts an arbitrary subtree
    /// here through `Tree`'s `emptyState`: an agent chat transcript, a marketplace list) had no
    /// box at all. The host declares its band in the slot's own `params_json`
    /// (`{"hostContentHeight": <px>}`), so the reservation costs one node and no measurement,
    /// and every other panel's node credit is untouched.
    fn admit_node_one(&mut self, tree: &UiTree, root_reversed: bool) -> (usize, usize) {
        let Some((id, parent)) = self.pending_node.take() else {
            self.admission = AdmissionPhase::Unwind;
            return (0, 0);
        };
        let Some(node) = tree.node(id) else {
            self.fault = Some(MountedLayoutFault::Stale);
            return (0, 0);
        };
        let parent_kind = parent.and_then(|index| self.nodes.as_deref().expect("live layout list owner").get(index)).map(|input| input.kind);
        let content = self.tree_content(tree, id, parent);
        let tree_inline_control = matches!(parent_kind, Some(LayoutNodeKind::TreeRow { .. } | LayoutNodeKind::TableRow { .. }));
        let tree_detail = parent.and_then(|index| self.nodes.as_deref().expect("live layout list owner").get(index)).is_some_and(|owner| is_tree_item_detail(tree, id, owner.id));
        let popup_overlay_row = tree.is_open_select_popup_row(id);
        let kind = if popup_overlay_row {
            LayoutNodeKind::OverlayRow { rect: FlexRect { x: node.layout.x, y: node.layout.y, width: node.layout.width, height: node.layout.height } }
        } else {
            if tree_detail {
                LayoutNodeKind::TreeDetail { height: TREE_DETAIL_HEIGHT }
            } else {
                match &node.spec.0 {
                    UiNode::Text(_) => LayoutNodeKind::Text,
                    UiNode::Tree(tree_node) => {
                        LayoutNodeKind::Tree { height: retained_tree_height(tree, id, tree_node, &self.row_metrics), header: if document_table(tree, id).is_some() { self.row_metrics.header_height } else { 0.0 }, reversed: root_reversed }
                    }
                    UiNode::Stack(stack) => content.is_none().then(|| tree_row_kind(tree, id, parent_kind, &self.row_metrics)).flatten().unwrap_or(LayoutNodeKind::Stack {
                        horizontal: stack.direction == "horizontal",
                        gap: gap_for_token(&self.theme, stack.gap.as_deref()),
                        padding: padding_for_token(&self.theme, stack.padding.as_deref()),
                    }),
                    UiNode::Field(_) | UiNode::Section(_) if content.is_some() => LayoutNodeKind::Leaf,
                    UiNode::Field(_) => LayoutNodeKind::Field { top: 0.0, bottom: 0.0 },
                    UiNode::Section(_) => LayoutNodeKind::Section { gap: self.theme.gap_standard, top: 0.0, bottom: 0.0 },
                    UiNode::Button(_) => LayoutNodeKind::Control { height: self.theme.control_height, label_padding: Some(self.theme.padding_standard) },
                    UiNode::Input(_) | UiNode::Select(_) => LayoutNodeKind::Control { height: if tree_inline_control { self.theme.control_height_small } else { self.theme.control_height }, label_padding: None },
                    UiNode::Toggle(_) | UiNode::Slider(_) | UiNode::NumberStepper(_) | UiNode::Ring(_) | UiNode::IconSelect(_) => LayoutNodeKind::Control { height: self.theme.control_height, label_padding: None },
                    UiNode::ExternalSlot(slot) => LayoutNodeKind::HostContent { height: host_content_height(&slot.params_json, &self.theme) },
                    UiNode::ComponentScene(_) => LayoutNodeKind::EngineSurface,
                    // 📶️ React's bar is `h-tiny w-full` (`🗣️Interpreter/🟦️.tsx`). As a plain `Leaf` it measured
                    // from arena children — a progress node has none — so it solved to height ZERO and
                    // `progress_bar_rects`' `SIZE_TINY.min(bounds.h)` painted nothing at all: the live
                    // generation3d Tool-runs panel showed the run title and an empty gap where React shows the
                    // filled bar (ticket 26/09/17/WGPU-RENDERER-REACT-PARITY,
                    // `📓️w14b-generation3d-labels-preview-layout.md`).
                    UiNode::Progress(_) => LayoutNodeKind::Control { height: crate::wgpu::chrome::SIZE_TINY, label_padding: None },
                    _ => LayoutNodeKind::Leaf,
                }
            }
        };
        let index = self.nodes.as_deref().expect("live layout list owner").len();
        let chrome = match &node.spec.0 {
            UiNode::Section(_) | UiNode::Field(_) if content.is_some() => ChromeTextRanges::None,
            UiNode::Section(section) => ChromeTextRanges::Section { title: section.label.as_ref().map(|_| GlyphRange::default()) },
            UiNode::Field(field) => ChromeTextRanges::Field { label: GlyphRange::default(), description: field.description.as_ref().map(|_| GlyphRange::default()), error: field.error.as_ref().map(|_| GlyphRange::default()) },
            UiNode::Slider(slider) if slider.unit.as_deref().is_some_and(|unit| !unit.is_empty()) => ChromeTextRanges::SliderUnit { label: GlyphRange::default() },
            _ => ChromeTextRanges::None,
        };
        let input = LayoutInputNode { id, parent, first_child: None, last_child: None, next_sibling: None, kind, intrinsic: IntrinsicSize::default(), glyph_start: 0, glyph_end: 0, chrome, content };
        if let Err(owner) = self.nodes.as_deref_mut().expect("live layout list owner").try_push(input) {
            self.rejected_node = Some(owner);
            self.fault = Some(MountedLayoutFault::NodeCredits);
            return (0, 0);
        }
        let metrics = retained_tree_row_metrics(tree, id, &self.row_metrics);
        if !self.flex.push(kind, parent, node.layout_spec.as_ref(), &metrics, parent_kind, content) {
            self.fault = Some(MountedLayoutFault::Solver);
            return (0, 0);
        }
        if let Some(parent) = parent {
            let previous = self.nodes.as_deref().expect("live layout list owner").get(parent).and_then(|owner| owner.last_child);
            match previous {
                Some(sibling) => {
                    if let Some(sibling) = self.nodes.as_deref_mut().expect("live layout list owner").get_mut(sibling) {
                        sibling.next_sibling = Some(index);
                    }
                }
                None => {
                    if let Some(owner) = self.nodes.as_deref_mut().expect("live layout list owner").get_mut(parent) {
                        owner.first_child = Some(index);
                    }
                }
            }
            if let Some(owner) = self.nodes.as_deref_mut().expect("live layout list owner").get_mut(parent) {
                owner.last_child = Some(index);
            }
        }
        let expanded = matches!(kind, LayoutNodeKind::TreeRow { .. } | LayoutNodeKind::TreeSection { .. }) || tree.disclosure_open(id).unwrap_or(true);
        if let Err(owner) = self.walk.as_deref_mut().expect("live layout list owner").try_push(WalkFrame { next_child: expanded.then_some(node.first_child).flatten(), node: index }) {
            self.rejected_walk = Some(owner);
            self.fault = Some(MountedLayoutFault::DepthCredits);
            return (0, 0);
        }
        if popup_overlay_row || !matches!(chrome, ChromeTextRanges::None) || matches!(kind, LayoutNodeKind::Text | LayoutNodeKind::Control { label_padding: Some(_), .. }) {
            self.text_node = Some(index);
            self.text_byte = 0;
            self.text_part = 0;
            self.text_glyph_start = self.glyphs.as_deref().expect("live layout list owner").len();
            if let Some(node) = self.nodes.as_deref_mut().expect("live layout list owner").get_mut(index) {
                node.glyph_start = self.glyphs.as_deref().expect("live layout list owner").len();
            }
            self.admission = AdmissionPhase::Text;
        } else {
            self.admission = AdmissionPhase::Unwind;
        }
        (1, 0)
    }

    /// 🧺️ How the node `id` under the admitted node `parent` lays out as tree-row content, when it is: a direct content
    /// child of a row whose content is more than one inline control takes its slot below the content before it
    /// (`reconcile::tree_row_content_lines`), a content container's children stack as columns and lines.
    fn tree_content(&self, tree: &UiTree, id: NodeId, parent: Option<usize>) -> Option<TreeContentFlow> {
        let owner = self.nodes.as_deref().expect("live layout list owner").get(parent?)?;
        let document = tree.document()?;
        let record = document.record(tree.document_id(id)?)?;
        let metrics = retained_tree_row_metrics(tree, id, &self.row_metrics);
        let (line, band) = (metrics.content_line_height(), metrics.content_line_height() + metrics.gap);
        let (above, below) = match &record.component {
            ui_contract::Component::Container(props) => crate::wgpu::reconcile::tree_content_label_lines(props),
            _ => (0, 0),
        };
        let (above, below) = (above as f32 * band, below as f32 * band);
        let container = matches!(record.component, ui_contract::Component::Container(_));
        if owner.content.is_some() {
            return Some(if container { TreeContentFlow::Column { above, below } } else { TreeContentFlow::Line { height: line } });
        }
        if !matches!(owner.kind, LayoutNodeKind::TreeRow { .. }) {
            return None;
        }
        let row = document.record(tree.document_id(owner.id)?)?;
        let total = crate::wgpu::reconcile::tree_row_content_lines(document, row)?;
        let lines_of = |child: &ui_contract::UiNodeRecord| u16::try_from(crate::wgpu::reconcile::tree_content_lines(document, child, 0)).unwrap_or(u16::MAX);
        let mut before = 0_u32;
        for child in crate::wgpu::reconcile::tree_row_content(document, row) {
            if child.id == record.id {
                let top = (metrics.row_height - tree_content_height(u16::try_from(total).unwrap_or(u16::MAX), line, metrics.gap)) * 0.5 + before as f32 * band;
                return Some(TreeContentFlow::Slot { top, height: tree_content_height(lines_of(child), line, metrics.gap), above, below, container });
            }
            before += u32::from(lines_of(child));
        }
        None
    }

    fn admit_text_one(&mut self, tree: &UiTree) -> (usize, usize) {
        let Some(index) = self.text_node else {
            self.admission = AdmissionPhase::Unwind;
            return (0, 0);
        };
        let Some(input) = self.nodes.as_deref().expect("live layout list owner").get(index).copied() else {
            self.fault = Some(MountedLayoutFault::Stale);
            return (0, 0);
        };
        let Some(spec) = tree.node(input.id).map(|node| &node.spec.0) else {
            self.fault = Some(MountedLayoutFault::Stale);
            return (0, 0);
        };
        let slider_unit_label = match spec {
            UiNode::Slider(slider) => slider.unit_label(),
            _ => None,
        };
        let part = match (spec, self.text_part) {
            (UiNode::Text(text), 0) => Some(Some(text.value.as_str())),
            (UiNode::Button(button), 0) => Some(Some(button.label.as_str())),
            (UiNode::Section(section), 0) => Some(section.label.as_ref().map(|label| label.as_str())),
            (UiNode::Field(field), 0) => Some(Some(field.label.as_str())),
            (UiNode::Field(field), 1) => Some(field.description.as_deref()),
            (UiNode::Field(field), 2) => Some(field.error.as_deref()),
            (UiNode::Slider(_), 0) => Some(slider_unit_label.as_deref()),
            (UiNode::Text(_) | UiNode::Button(_) | UiNode::Section(_) | UiNode::Slider(_), 1..) | (UiNode::Field(_), 3..) => None,
            _ => {
                self.fault = Some(MountedLayoutFault::Stale);
                return (0, 0);
            }
        };
        let Some(value) = part else {
            let run = RetainedTextRun { node: index, glyph_start: input.glyph_start, glyph_end: self.glyphs.as_deref().expect("live layout list owner").len() };
            if let Err(owner) = self.runs.as_deref_mut().expect("live layout list owner").try_push(run) {
                self.rejected_run = Some(owner);
                self.fault = Some(MountedLayoutFault::NodeCredits);
                return (0, 0);
            }
            if let Some(node) = self.nodes.as_deref_mut().expect("live layout list owner").get_mut(index) {
                node.glyph_start = run.glyph_start;
                node.glyph_end = run.glyph_end;
            }
            self.text_node = None;
            self.text_byte = 0;
            self.text_part = 0;
            self.admission = AdmissionPhase::Unwind;
            return (0, 0);
        };
        let Some(value) = value else {
            self.record_chrome_range(index, self.text_part, None);
            self.text_part += 1;
            self.text_byte = 0;
            self.text_glyph_start = self.glyphs.as_deref().expect("live layout list owner").len();
            return (0, 0);
        };
        let Some(scalar) = value.get(self.text_byte..).and_then(|tail| tail.chars().next()) else {
            self.record_chrome_range(index, self.text_part, Some(GlyphRange { start: self.text_glyph_start, end: self.glyphs.as_deref().expect("live layout list owner").len() }));
            self.text_part += 1;
            self.text_byte = 0;
            self.text_glyph_start = self.glyphs.as_deref().expect("live layout list owner").len();
            return (0, 0);
        };
        self.text_byte += scalar.len_utf8();
        if let Err(owner) = self.glyphs.as_deref_mut().expect("live layout list owner").try_push(RetainedGlyphInput { node: index, scalar }) {
            self.rejected_glyph = Some(owner);
            self.fault = Some(MountedLayoutFault::GlyphCredits);
            return (0, 0);
        }
        (0, 1)
    }

    fn record_chrome_range(&mut self, index: usize, part: u8, range: Option<GlyphRange>) {
        let Some(node) = self.nodes.as_deref_mut().expect("live layout list owner").get_mut(index) else {
            self.fault = Some(MountedLayoutFault::Stale);
            return;
        };
        match (&mut node.chrome, part) {
            (ChromeTextRanges::Section { title }, 0) => *title = range,
            (ChromeTextRanges::Field { label, .. }, 0) => *label = range.unwrap_or_default(),
            (ChromeTextRanges::Field { description, .. }, 1) => *description = range,
            (ChromeTextRanges::Field { error, .. }, 2) => *error = range,
            (ChromeTextRanges::SliderUnit { label }, 0) => *label = range.unwrap_or_default(),
            (ChromeTextRanges::None, _) => {}
            _ => self.fault = Some(MountedLayoutFault::Stale),
        }
    }

    fn unwind_one(&mut self, tree: &UiTree) -> (usize, usize) {
        let Some(frame) = self.walk.as_deref_mut().expect("live layout list owner").last_mut() else {
            self.admission = AdmissionPhase::Ready;
            return (0, 0);
        };
        if let Some(child) = frame.next_child {
            frame.next_child = tree.node(child).and_then(|node| node.next_sibling);
            self.pending_node = Some((child, Some(frame.node)));
            self.admission = if self.block_reversed { AdmissionPhase::VisitReversed } else { AdmissionPhase::Visit };
            return (0, 0);
        }
        self.walk.as_deref_mut().expect("live layout list owner").pop();
        (1, 0)
    }

    fn worker_one(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
        #[cfg(test)]
        {
            self.worker_thread_observed = std::thread::current().name().is_some_and(|name| name.starts_with("semio-pool-worker-"));
        }
        if self.close_requested || cx.is_cancelled() {
            return semio_framework_job::StepOutcome::Cancelled;
        }
        if cx.should_yield() {
            return semio_framework_job::StepOutcome::Yield;
        }
        cx.set_stage(self.stage_label());
        match self.stage {
            LayoutJobStage::ShapeText => self.shape_one(),
            LayoutJobStage::MeasureLayout => self.measure_one(),
            LayoutJobStage::SolveLayout => self.arrange_one(),
            LayoutJobStage::CollectResults => self.collect_one(),
            _ => (0, 0),
        };
        cx.consume_fuel(1);
        if cx.is_cancelled() {
            return semio_framework_job::StepOutcome::Cancelled;
        }
        if self.fault.is_some() {
            return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::Fault) });
        }
        if cx.deadline_exceeded() {
            return semio_framework_job::StepOutcome::Yield;
        }
        if self.stage == LayoutJobStage::PublishResults {
            semio_framework_job::StepOutcome::PreviewReady(semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::Preview))
        } else {
            semio_framework_job::StepOutcome::Yield
        }
    }

    fn shape_one(&mut self) -> (usize, usize) {
        let Some(run) = self.runs.as_deref().expect("live layout list owner").get(self.run_cursor).copied() else {
            if self.flex.len() != self.nodes.as_deref().expect("live layout list owner").len() {
                self.fault = Some(MountedLayoutFault::Solver);
                return (0, 0);
            }
            self.measure_cursor = self.nodes.as_deref().expect("live layout list owner").len();
            self.stage = LayoutJobStage::MeasureLayout;
            return (0, 0);
        };
        if self.glyph_cursor < run.glyph_start {
            self.glyph_cursor = run.glyph_start;
            return (0, 0);
        }
        if self.glyph_cursor >= run.glyph_end {
            self.run_cursor += 1;
            return (0, 0);
        }
        let Some(input) = self.glyphs.as_deref().expect("live layout list owner").get(self.glyph_cursor).copied() else {
            self.fault = Some(MountedLayoutFault::Stale);
            return (0, 0);
        };
        let next = self.glyphs.as_deref().expect("live layout list owner").get(self.glyph_cursor + 1).filter(|_| self.glyph_cursor + 1 < run.glyph_end).map(|glyph| glyph.scalar);
        let raw_preview = self.text_worker.shape_one(input, next);
        let preview = match self.atlas_candidate.retain_one(input.scalar, self.generation, self.revision, raw_preview) {
            Ok(Some(preview)) => preview,
            Ok(None) => return (0, 0),
            Err(fault) => {
                self.fault = Some(fault);
                return (0, 0);
            }
        };
        if let Err(owner) = self.glyph_previews.as_deref_mut().expect("live layout list owner").try_push(preview) {
            self.rejected_preview = Some(owner);
            self.fault = Some(MountedLayoutFault::GlyphCredits);
            return (0, 0);
        }
        if let Some(node) = self.nodes.as_deref_mut().expect("live layout list owner").get_mut(input.node) {
            node.intrinsic.width += preview.advance + preview.kerning;
            node.intrinsic.height = node.intrinsic.height.max(preview.height);
        }
        self.glyph_cursor += 1;
        (0, 1)
    }

    /// 👶️ Collects node `index`'s direct children into the reusable scratch buffer, in document
    /// order — the sibling links admission built, so no scan over the node array is ever needed.
    fn gather_children(&mut self, index: usize) {
        self.child_scratch.clear();
        let mut cursor = self.nodes.as_deref().expect("live layout list owner").get(index).and_then(|owner| owner.first_child);
        while let Some(child) = cursor {
            self.child_scratch.push(child);
            cursor = self.nodes.as_deref().expect("live layout list owner").get(child).and_then(|owner| owner.next_sibling);
        }
    }

    /// 📏️ Measures exactly ONE node's intrinsic size, walking the admission order in REVERSE so every
    /// child is already measured when its parent is reached. Work in this grant is that node's child
    /// count, never its subtree.
    fn measure_one(&mut self) -> (usize, usize) {
        let Some(index) = self.measure_cursor.checked_sub(1) else {
            self.arrange_cursor = 0;
            let root = FlexRect { x: 0.0, y: 0.0, width: self.width, height: self.height };
            if !self.flex.set_root_box(0, root) {
                self.fault = Some(MountedLayoutFault::Solver);
            }
            self.stage = LayoutJobStage::SolveLayout;
            return (0, 0);
        };
        self.measure_cursor = index;
        self.gather_children(index);
        let chrome = self.nodes.as_deref().expect("live layout list owner").get(index).and_then(|node| composite_chrome(node, self.glyphs.as_deref().expect("live layout list owner"), self.glyph_previews.as_deref().expect("live layout list owner"), self.width, self.theme.gap_standard));
        if let Some((top, bottom)) = chrome {
            if !self.flex.set_composite_chrome(index, top, bottom) {
                self.fault = Some(MountedLayoutFault::Solver);
                return (0, 0);
            }
        }
        let Self { flex, nodes, glyphs, glyph_previews, child_scratch, .. } = self;
        let (Some(nodes_ref), Some(glyphs_ref), Some(previews_ref)) = (nodes.as_deref(), glyphs.as_deref(), glyph_previews.as_deref()) else { self.fault = Some(MountedLayoutFault::Stale); return (0, 0); };
        let mut measure = |node: usize, constraint: MeasureConstraint| measure_text(nodes_ref, glyphs_ref, previews_ref, node, constraint);
        if !flex.measure_one(index, child_scratch, &mut measure) {
            self.fault = Some(MountedLayoutFault::Solver);
            return (0, 0);
        }
        (1, 0)
    }

    /// 📐️ Arranges exactly ONE container's direct children inside its own already-resolved box,
    /// walking the admission order FORWARD so a parent's box is always settled before its children
    /// are placed. This is the grant the eight-millisecond slice law is charged against: its cost is
    /// the container's child count, so a 1,025-node surface is ~1,025 small solves, never one large one.
    fn arrange_one(&mut self) -> (usize, usize) {
        if self.nodes.as_deref().expect("live layout list owner").get(self.arrange_cursor).is_none() {
            self.stage = LayoutJobStage::CollectResults;
            return (0, 0);
        }
        let index = self.arrange_cursor;
        self.arrange_cursor += 1;
        self.gather_children(index);
        if self.child_scratch.is_empty() {
            return (1, 0);
        }
        let width = self.flex.rect(index).map_or(self.width, |rect| rect.width);
        let chrome = self.nodes.as_deref().expect("live layout list owner").get(index).and_then(|node| composite_chrome(node, self.glyphs.as_deref().expect("live layout list owner"), self.glyph_previews.as_deref().expect("live layout list owner"), width, self.theme.gap_standard));
        if let Some((top, bottom)) = chrome {
            if !self.flex.set_composite_chrome(index, top, bottom) {
                self.fault = Some(MountedLayoutFault::Solver);
                return (0, 0);
            }
        }
        let Self { flex, nodes, glyphs, glyph_previews, child_scratch, .. } = self;
        let (Some(nodes_ref), Some(glyphs_ref), Some(previews_ref)) = (nodes.as_deref(), glyphs.as_deref(), glyph_previews.as_deref()) else { self.fault = Some(MountedLayoutFault::Stale); return (0, 0); };
        let mut measure = |node: usize, constraint: MeasureConstraint| measure_text(nodes_ref, glyphs_ref, previews_ref, node, constraint);
        if !flex.arrange_one(index, child_scratch, &mut measure) {
            self.fault = Some(MountedLayoutFault::Solver);
            return (0, 0);
        }
        (1, 0)
    }

    /// 📐️ Reads exactly ONE solved box back out of the flex tree, in admission order so
    /// `results[i]` stays the box of `nodes[i]` — the invariant `publish_one` re-checks.
    fn collect_one(&mut self) -> (usize, usize) {
        let Some(input) = self.nodes.as_deref().expect("live layout list owner").get(self.collect_cursor).copied() else {
            self.stage = LayoutJobStage::PublishResults;
            return (0, 0);
        };
        let Some(rect) = self.flex.rect(self.collect_cursor) else {
            self.fault = Some(MountedLayoutFault::Solver);
            return (0, 0);
        };
        let index = self.collect_cursor;
        self.collect_cursor += 1;
        if matches!(input.kind, LayoutNodeKind::Text | LayoutNodeKind::Control { label_padding: Some(_), .. } | LayoutNodeKind::OverlayRow { .. } | LayoutNodeKind::Field { .. } | LayoutNodeKind::Section { .. })
            || matches!(input.chrome, ChromeTextRanges::SliderUnit { .. })
        {
            if let Err(owner) = self.lines.as_deref_mut().expect("live layout list owner").try_push(RetainedLine { node: index, width: rect.width, height: rect.height }) {
                self.rejected_line = Some(owner);
                self.fault = Some(MountedLayoutFault::NodeCredits);
                return (0, 0);
            }
            self.line_cursor += 1;
        }
        let inline_suffix_width = if matches!(input.chrome, ChromeTextRanges::SliderUnit { .. }) { input.intrinsic.width } else { 0.0 };
        if let Err(owner) = self.results.as_deref_mut().expect("live layout list owner").try_push(MountedLayoutResult { id: input.id, x: rect.x, y: rect.y, width: rect.width, height: rect.height, inline_suffix_width }) {
            self.rejected_result = Some(owner);
            self.fault = Some(MountedLayoutFault::NodeCredits);
            return (0, 0);
        }
        (1, 0)
    }

    pub(crate) fn take_preview_one(&mut self) -> Option<MountedLayoutResult> {
        let preview = self.results.as_deref().expect("live layout list owner").get(self.preview_cursor).copied()?;
        self.preview_cursor += 1;
        Some(preview)
    }

    pub(crate) fn latest_glyph_preview(&self) -> Option<RetainedGlyphPreview> {
        self.glyph_previews.as_deref().expect("live layout list owner").get(self.glyph_cursor.saturating_sub(1)).copied()
    }

    pub(crate) fn root_intrinsic_height(&self) -> Option<f32> {
        if matches!(self.stage, LayoutJobStage::CollectNodes | LayoutJobStage::ShapeText | LayoutJobStage::MeasureLayout) {
            return None;
        }
        self.flex.intrinsic(0).map(|(_, height)| height)
    }

