    pub(crate) fn worker_thread_observed(&self) -> bool {
        self.worker_thread_observed
    }

    #[cfg(test)]
    fn rejected_glyph(&self) -> Option<RetainedGlyphInput> {
        self.rejected_glyph
    }

    #[cfg(test)]
